import pathlib,json
class Reader:
 def __init__(self,b):self.b=b;self.i=0
 def byte(self):v=self.b[self.i];self.i+=1;return v
 def integer(self):
  v=0;s=0
  while True:
   c=self.byte();v|=(c&127)<<s
   if c<128:return v
   s+=7
 def take(self,n):v=self.b[self.i:self.i+n];self.i+=n;return v
 def string(self):return self.take(self.integer()).decode()
def sections(p):
 r=Reader(pathlib.Path(p).read_bytes());r.take(8);out=[]
 while r.i<len(r.b):
  k=r.byte();out.append((k,r.take(r.integer())))
 return out

